#include <Cellerator/compiler/ir/planning/implement_user_edits_and_authority_hierarchy_v1.hh>
namespace cellerator::compiler::ir::planning::v1 {
search_edit_status_v1 validate_search_space_edit_v1(const search_space_edit_v1&v,std::uint64_t min) noexcept{if((!v.edit.low&&!v.edit.high)||(!v.actor.low&&!v.actor.high)||(!v.subject.low&&!v.subject.high))return search_edit_status_v1::invalid_identity;if(static_cast<unsigned>(v.kind)>7)return search_edit_status_v1::invalid_kind;if(static_cast<unsigned>(v.authority)>4)return search_edit_status_v1::invalid_authority;if(v.reserved8)return search_edit_status_v1::nonzero_reserved;if(v.sequence<min)return search_edit_status_v1::stale_edit;if(v.kind==search_edit_kind_v1::force_selection&&v.authority<edit_authority_v1::user_force)return search_edit_status_v1::authority_mismatch;if(v.kind==search_edit_kind_v1::unsafe_assertion&&(v.authority!=edit_authority_v1::unsafe_user_assertion||!v.unsafe_acknowledged))return search_edit_status_v1::unsafe_not_acknowledged;return search_edit_status_v1::ok;}
bool edit_overrides_v1(const search_space_edit_v1&a,const search_space_edit_v1&b) noexcept{return a.subject.low==b.subject.low&&a.subject.high==b.subject.high&&(a.authority>b.authority||(a.authority==b.authority&&a.sequence>b.sequence));}
}
